"""Plantilla HTML de la pantalla de auditoria de una operacion.

Modulo de un solo dato: `TRADE_AUDIT_HTML`, la pagina completa (HTML + CSS +
JS) que muestra la evidencia de por que se tomo una operacion y como
evoluciono: contexto de entrada, calidad, patrones y linea de tiempo de
snapshots "entrada vs ahora".

Es la vista clave para revisar cierres: permite comprobar si una salida
respondio a la estructura del trade o a otra causa.

Vinculaciones:
    - `dashboard.realtime_dashboard`: sirve esta cadena y expone el endpoint de
      auditoria que la alimenta.
    - `database.repository`: tablas `trade_visual_audits` y
      `trade_audit_snapshots`, origen de los datos.
"""

TRADE_AUDIT_HTML = r"""<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BlackDaemonFX · Auditoría del trade</title>
<style>:root{color-scheme:dark;--bg:#050708;--p:#0a0e10;--p2:#10161a;--p3:#151d22;--t:#f5f5f2;--m:#9fa2a5;--l:#5b4514;--g:#00db79;--r:#ff453a;--y:#f5bd36;--b:#53a7ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--t);font:14px system-ui}.w{max-width:1380px;margin:auto;padding:18px}.brand{display:flex;align-items:center;gap:12px;border-bottom:1px solid var(--l);padding-bottom:12px}.brand img{width:54px;height:54px;border-radius:10px;border:1px solid #765719}.brand b{font-size:20px;letter-spacing:.04em}.brand span{color:#f4c84f}.top{display:flex;justify-content:space-between;gap:12px;align-items:end;flex-wrap:wrap;margin:18px 0}.top h1{margin:0}.muted{color:var(--m)}.btn{display:inline-block;color:var(--t);background:var(--p2);border:1px solid var(--l);padding:8px 11px;border-radius:8px;text-decoration:none;font-size:12px}.toolbar{display:flex;gap:8px;flex-wrap:wrap}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:12px}.card{background:var(--p);border:1px solid var(--l);border-radius:13px;padding:14px;min-width:0}.k{grid-column:span 3}.half{grid-column:span 6}.full{grid-column:1/-1}.lab{font-size:10px;color:var(--m);text-transform:uppercase;letter-spacing:.06em}.val{font-size:20px;font-weight:800;margin-top:5px}.good{color:var(--g)}.bad{color:var(--r)}.warn{color:var(--y)}.pill{display:inline-block;border:1px solid #3c351d;border-radius:99px;padding:3px 7px;margin:2px;font-size:10px;background:var(--p3);overflow-wrap:anywhere}.decision{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border-radius:7px;background:var(--p3);border-left:3px solid var(--b);font-weight:800}.viewData{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin-top:10px}.datum{padding:7px;background:var(--p2);border-radius:7px;color:var(--m);font-size:11px}.datum b{display:block;color:var(--t);font-size:13px;margin-top:2px}.rr{font-size:20px;font-weight:900;color:var(--y)}.quality{margin-top:10px}.quality summary,.technical summary{cursor:pointer;color:var(--m);font-size:12px}.summary{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-top:10px}.mini{background:var(--p2);padding:10px;border-radius:8px}.mini b{display:block;font-size:17px;margin-top:3px}.timeline{margin-top:12px;position:relative}.snap{display:grid;grid-template-columns:170px 1fr;gap:12px;padding:0 0 14px;margin-bottom:14px;border-bottom:1px solid #263036}.snapTime{color:var(--m);font-size:12px;padding:10px;background:var(--p2);border-radius:9px;height:max-content}.snapTime b{color:var(--t);font-size:14px}.snapshotBody{display:grid;grid-template-columns:1.2fr .8fr;gap:10px;min-width:0}.view{background:var(--p2);border-radius:9px;padding:11px;min-width:0}.viewTitle{font-size:10px;color:var(--m);letter-spacing:.06em;margin-bottom:8px}.technical{background:var(--p2);border-radius:9px;padding:11px;min-width:0}.json{white-space:pre-wrap;overflow-wrap:anywhere;color:#b8c0c5;font:11px ui-monospace,monospace;max-height:280px;overflow-y:auto;margin:9px 0 0}.empty{padding:20px;color:var(--m)}@media(max-width:900px){.k,.half{grid-column:span 6}.summary{grid-template-columns:repeat(3,1fr)}.snap{grid-template-columns:1fr}.snapshotBody{grid-template-columns:1fr}}@media(max-width:560px){.k,.half{grid-column:1/-1}.summary,.viewData{grid-template-columns:repeat(2,1fr)}.w{padding:10px}}</style></head><body><main class="w">
<div class="brand"><img src="/assets/blackdaemonfx_logo.jpeg" alt="Logo BlackDaemonFX"><div><b>BLACKDAEMON<span>FX</span></b><div class="muted">AUDITORÍA VISUAL · ENTRADA VS. AHORA</div></div></div>
<div class="top"><div><h1 id="title">Cargando trade…</h1><div id="subtitle" class="muted"></div></div><div class="toolbar"><a class="btn" id="excelBtn" href="#">Exportar Excel ↓</a><a class="btn" href="/account">← Cuenta</a><a class="btn" href="/">Dashboard</a></div></div>
<section class="grid"><div class="card k"><div class="lab">Dirección</div><div class="val" id="direction">—</div></div><div class="card k"><div class="lab">Estado / cierre</div><div class="val" id="status">—</div></div><div class="card k"><div class="lab">RR real</div><div class="val" id="rr">—</div></div><div class="card k"><div class="lab">PnL</div><div class="val" id="pnl">—</div></div>
<div class="card half"><div class="lab">Tesis al abrir</div><div id="entry">—</div></div><div class="card half"><div class="lab">Último estado observado</div><div id="current">—</div></div><div class="card full"><div class="lab">Resumen de evolución</div><div class="summary" id="summary"></div></div><div class="card full"><div class="lab">Línea temporal completa · SQLAlchemy</div><div class="muted" style="font-size:12px;margin-top:5px">Cada punto conserva la lectura de mercado de ese instante. El JSON técnico queda oculto hasta que sea necesario revisarlo.</div><div id="timeline" class="timeline"></div></div></section></main>
<script>const $=x=>document.getElementById(x),e=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),n=(v,d=2)=>v==null?'—':Number(v).toFixed(d),money=v=>v==null?'—':Number(v).toLocaleString('es-CL',{minimumFractionDigits:2,maximumFractionDigits:2}),pills=a=>(a||[]).map(x=>'<span class="pill">'+e(x)+'</span>').join('');
function view(v,m,isEntry){v=v||{};m=m||{};let decision=v.decision||v.state||v.action||'—',score=v.score??v.trade_score??'—',confirmation=v.confirmation_percentage??'—';return '<div class="decision">'+e(decision)+'</div>'+(isEntry?'':'<div class="rr">R actual: '+e(m.current_rr??'—')+'</div>')+'<div class="viewData"><div class="datum">Score<b>'+e(score)+'</b></div><div class="datum">Confirmación<b>'+e(confirmation)+'%</b></div><div class="datum">Tendencia H1<b>'+e(v.h1_trend||'—')+'</b></div><div class="datum">Estructura<b>'+e(v.structure_break||'—')+'</b></div><div class="datum">Zona<b>'+e(v.zone||'—')+'</b></div><div class="datum">Patrón<b>'+e(v.chart_pattern_name?String(v.chart_pattern_name).replaceAll('_',' '):'—')+'</b></div></div><details class="quality"><summary>Confirmaciones aprobadas ('+e((v.passed_confirmations||v.confirmations_passed||[]).length)+')</summary><div>'+pills(v.passed_confirmations||v.confirmations_passed)+'</div></details>'}
function timelineItem(x,i){let c=x.current_view||{},m=x.market||{},v=x.visual_context||{};return '<article class="snap"><div class="snapTime"><b>Snapshot #'+(i+1)+'</b><br>'+e(x.snapshot_at?new Date(x.snapshot_at).toLocaleString('es-CL'):'—')+'<br><span class="rr">R '+e(m.current_rr??'—')+'</span></div><div class="snapshotBody"><div class="view"><div class="viewTitle">LO QUE VEÍA EN ESE MOMENTO</div>'+view(c,m,false)+'</div><details class="technical"><summary>Contexto técnico persistido</summary><pre class="json">'+e(JSON.stringify({market:m,visual_context:v},null,2))+'</pre></details></div></article>'}
function render(a){let t=a.trade||{},s=a.snapshots||[],entry=a.entry_view||{},last=a.latest||{},cv=last.current_view||{},mk=last.market||{},eb=$('excelBtn');if(eb)eb.href='/api'+location.pathname+'/excel';$('title').textContent=(t.instrument||'Trade')+' · Trade #'+(t.id??t.source_trade_id??'—');$('subtitle').textContent='Entrada '+(t.entry_time?new Date(t.entry_time).toLocaleString('es-CL'):'—')+' · '+s.length+' snapshots históricos';$('direction').textContent=t.direction||'—';$('status').textContent=(t.status||'—')+' · '+(t.classification||t.result||'—');$('rr').textContent=n(t.realized_rr);$('pnl').textContent=money(t.net_pnl);$('pnl').className='val '+(Number(t.net_pnl||0)>0?'good':Number(t.net_pnl||0)<0?'bad':'');$('entry').innerHTML=view(entry,{},true);$('current').innerHTML=view(cv,mk,false);let rrs=s.map(x=>Number((x.market||{}).current_rr)).filter(Number.isFinite),max=rrs.length?Math.max(...rrs):null,min=rrs.length?Math.min(...rrs):null;$('summary').innerHTML='<div class="mini">Snapshots<b>'+e(s.length)+'</b></div><div class="mini">MFE observado<b>'+e(max==null?'—':max.toFixed(2)+'R')+'</b></div><div class="mini">MAE observado<b>'+e(min==null?'—':min.toFixed(2)+'R')+'</b></div><div class="mini">Inicio<b>'+e(s.length?new Date(s[0].snapshot_at).toLocaleTimeString('es-CL'):'—')+'</b></div><div class="mini">Último<b>'+e(s.length?new Date(s[s.length-1].snapshot_at).toLocaleTimeString('es-CL'):'—')+'</b></div>';$('timeline').innerHTML=s.map(timelineItem).join('')||'<div class="empty">Este trade todavía no tiene snapshots históricos.</div>'}async function go(){try{let r=await fetch('/api'+location.pathname+'?x='+Date.now(),{cache:'no-store'});if(!r.ok)throw new Error(await r.text());render(await r.json())}catch(err){$('title').textContent='No se pudo cargar la auditoría';$('subtitle').textContent=err.message}}go();</script></body></html>"""
